package com.bombay.restaurantintelligence.web;
import com.bombay.restaurantintelligence.analytics.*; import org.springframework.format.annotation.DateTimeFormat; import org.springframework.web.bind.annotation.*; import java.time.LocalDate;
@RestController @RequestMapping("/api/analytics") public class AnalyticsController {private final KPIService kpis;private final VendorAnalyticsService vendors;public AnalyticsController(KPIService kpis,VendorAnalyticsService vendors){this.kpis=kpis;this.vendors=vendors;}@GetMapping("/dashboard") public AnalyticsService.DashboardData dashboard(@RequestParam(required=false)@DateTimeFormat(iso=DateTimeFormat.ISO.DATE)LocalDate from,@RequestParam(required=false)@DateTimeFormat(iso=DateTimeFormat.ISO.DATE)LocalDate to){return kpis.dashboard(from,to);}@GetMapping("/vendors/{vendor}") public java.util.Map<String,Object> vendor(@PathVariable String vendor,@RequestParam@DateTimeFormat(iso=DateTimeFormat.ISO.DATE)LocalDate from,@RequestParam@DateTimeFormat(iso=DateTimeFormat.ISO.DATE)LocalDate to){return java.util.Map.of("vendor",vendor,"from",from,"to",to,"amount",vendors.vendorSpend(vendor,from,to));}}
